, '[object Object]', '[object Object]', '[object Object]', '21 days accommodation included', 'Activities packages included', 'Iconic viewpoints', 'Full access to the private members group', 'Flight assistance', 'Experienced ACE Rep travelling with you', 'Local Thai guide', 'International flights', 'Travel insurance', 'Lunches and some dinners', 'Personal expenses', 'Optional activities', 'Visa fees (if applicable)', 'Tips', 1, '2026-04-01 13:05:21.000', '2026-04-19 10:51:54.000', 1, , `flyIn` = '', `flyOut` = '', `notes` = '', 'Thailand Island Hopper Tour | 21-Day Group Adventure | ACE Travel Experiences', 'Explore Thailand\'s most iconic islands on our 21-day group tour for 18-35s. From Bangkok to Koh Samui, Koh Phangan & Koh Tao. Just £1,599 with a £60 deposit. Small groups, big memories.');
