dation included', 'Activities packages included', 'Experienced ACE Rep & Local Guide', 'Iconic viewpoints', 'Private group WhatsApp', 'Flight assistance', 'Flexible payment plan', '14 meals', 'International flights', 'Travel insurance', 'Personal expenses', 'Optional activities (scuba diving, spa)', 'Visa on arrival fee (if applicable)', 'Tips', 1, '2026-04-01 13:05:21.000', '2026-04-19 10:51:54.000', 2, NULL, NULL, 'Bali Explorer Tour | 14-Day Group Adventure | ACE Travel Experiences', 'Discover the best of Bali on our 14-day group tour for 18-35s. Canggu, Ubud, Nusa Lembongan & Uluwatu. From £1,199 with a £60 deposit. Real experiences, lifelong friendships.');
INSERT IGNORE INTO `tours` (`id`, `slug`, `name`, `destination`, `duration`, `price`, `deposit`, `groupSize`, `ageRange`, `rating`, `reviews`, `nextDeparture`, `heroImage`, `gallery`, `description`, `highlights`, `itinerary`, `included`, `notIncluded`, `published`, `createdAt`, `updatedAt`, `sortOrder`, `departureDates`, `flightInfo`, `seoTitle`, `seoDescription`) VALUES (3, 'thailand-intro', 'Thailand Intro', 'Thailand', '12 days', '£999', '£60', '15-30', '18-35', '4.9', 156, 'Dates Coming Soon', 'https://files.manuscdn.com/user_upload_by_module/session_file/310519663269568751/tsHbOJIkOEbtvFOv.jpg', , '12 days exploring the best of Thailand. From the buzzing streets of Bangkok to the mountain town of Chiang Mai and the laid-back paradise of Pai. Culture, adventure, and unforgettable friendships await.', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '11 nights accommodation (hostels and guesthouses)', '14 meals (breakfast and group dinners)', 'Experienced Ace Rep & Local Guide', 'Activities packages included (Elephant Sanctuary, Tipsy Tubing, Temple visits, Sticky Waterfalls)', 'All activities and entrance fees', 'Iconic viewpoints', 'Private WhatsApp group', 'Flight assistance', 'Airport pickup', 'All inter-destination transport including night train', '24/7 emergency support', 'International flights', 'Travel insurance (mandatory)', 'Lunches and some dinners', 'Personal expenses and souvenirs', 'Optional activities (Khatok Dinner, Hot Springs & Nam Lod Cave)', 'Visa fees (if applicable)', 'Tips for guides and drivers', 1, '2026-04-01 13:05:21.000', '2026-04-19 10:51:54.000', 3, NULL, NULL, 'Thailand Intro Tour | 12-Day Group Adventure | ACE Travel Experiences', 'Your perfect introduction to Thailand. 12 days through Bangkok, Chiang Mai & Pai with a small group of 18-35s. From £999 with a £60 deposit. Elephant sanctuaries, temples & more.');
