INSERT IGNORE INTO `deals` (`id`, `title`, `description`, `discount`, `validUntil`, `image`, `tourId`, `active`, `createdAt`, `updatedAt`, `sortOrder`, `slug`, `tagline`) VALUES (1, 'Early Bird — Thailand Island Hopper', 'Book your April 2026 Thailand Island Hopper departure before 31st March and save £100 off the tour price. Limited spaces available at this rate.', '£100 off', '31 March 2026', 'https://files.manuscdn.com/user_upload_by_module/session_file/310519663269568751/nbdFlsyYCgCVjCdb.jpeg', NULL, 1, '2026-04-01 13:05:22.000', '2026-04-01 13:05:22.000', 1, NULL, NULL);
INSERT IGNORE INTO `deals` (`id`, `title`, `description`, `discount`, `validUntil`, `image`, `tourId`, `active`, `createdAt`, `updatedAt`, `sortOrder`, `slug`, `tagline`) VALUES (2, 'Summer Bali Explorer — Summer Holiday Friendly', 'Our 31st July departure is perfectly timed for UK summer holidays. Grab your spot before it sells out — this is our most popular Bali Explorer date.', 'Limited spaces', 'While spaces last', 'https://files.manuscdn.com/user_upload_by_module/session_file/310519663269568751/ZyduANpQpBJQSfsk.jpeg', NULL, 1, '2026-04-01 13:05:22.000', '2026-04-01 13:05:22.000', 2, NULL, NULL);
INSERT IGNORE INTO `deals` (`id`, `title`, `description`, `discount`, `validUntil`, `image`, `tourId`, `active`, `createdAt`, `updatedAt`, `sortOrder`, `slug`, `tagline`) VALUES (3, 'Refer a Friend', 'Get £50 off your next booking when you refer a friend who books a tour with ACE Travel Experiences. Your friend also gets £50 off their first booking!', '£50 each', 'Ongoing', 'https://files.manuscdn.com/user_upload_by_module/session_file/310519663269568751/yKqEZpaSqHKvosnK.jpeg', NULL, 1, '2026-04-01 13:05:22.000', '2026-04-01 13:05:22.000', 3, NULL, NULL);
INSERT IGNORE INTO `reviews` (`id`, `authorName`, `authorAge`, `authorLocation`, `authorPhoto`, `rating`, `reviewText`, `tourSlug`, `tourName`, `reviewDate`, `published`, `featured`, `sortOrder`, `createdAt`, `updatedAt`) VALUES (1, 'Chloe', NULL, NULL, NULL, 5, 'Second Ace trip and incredible again! Perfect for solo travellers. Met amazing people, hiked Mt Batur, released baby turtles! Clean, comfy stays. Can\'t wait for number three!', 'bali-explorer', 'Bali Explorer', '24 Sep 2025', 1, 1, 1, '2026-04-01 13:05:21.000', '2026-04-01 13:05:21.000');
INSERT IGNORE INTO `reviews` (`id`, `authorName`, `authorAge`, `authorLocation`, `authorPhoto`, `rating`, `reviewText`, `tourSlug`, `tourName`, `reviewDate`, `published`, `featured`, `sortOrder`, `createdAt`, `updatedAt`) VALUES (2, 'Ellie Heinsen', NULL, NULL, NULL, 5, 'Absolutely incredible! Perfect balance of culture, exploring, and partying. Ace team was helpful from booking to end. Mt Batur hike was unforgettable! First solo trip and it boosted my confidence to travel more.', 'bali-explorer', 'Bali Explorer', '19 Sep 2025', 1, 1, 2, '2026-04-01 13:05:21.000', '2026-04-01 13:05:21.000');
INSERT IGNORE INTO `reviews` (`id`, `authorName`, `authorAge`, `authorLocation`, `authorPhoto`, `rating`, `reviewText`, `tourSlug`, `tourName`, `reviewDate`, `published`, `featured`, `sortOrder`, `createdAt`, `updatedAt`) VALUES (3, 'Maisie', NULL, NULL, NULL, 5, 'Second trip with Ace! They do everything right. Never nervous because everything\'s covered. Bucket list activities like turtle conservation! Already planning trip three. Amazing support and instant friendships.', 'bali-explorer', 'Bali Explorer', '23 Sep 2025', 1, 1, 3, '2026-04-01 13:05:21.000', '2026-04-01 13:05:21.000');
INSERT IGNORE INTO `reviews` (`id`, `authorName`, `authorAge`, `authorLocation`, `authorPhoto`, `rating`, `reviewText`, `tourSlug`, `tourName`, `reviewDate`, `published`, `featured`, `sortOrder`, `createdAt`, `updatedAt`) VALUES (4, 'Charlotte', NULL, NULL, NULL, 5, 'Best time of my life! Perfect for first-time travellers. Ace handles everything so you don\'t worry about a thing. Life changing experience!', 'bali-explorer', 'Bali Explorer', '24 Apr 2025', 1, 1, 4, '2026-04-01 13:05:21.000', '2026-04-01 13:05:21.000');
INSERT IGNORE INTO `reviews` (`id`, `authorName`, `authorAge`, `authorLocation`, `authorPhoto`, `rating`, `reviewText`, `tourSlug`, `tourName`, `reviewDate`, `published`, `featured`, `sortOrder`, `createdAt`, `updatedAt`) VALUES (5, 'Hannah Taylor', NULL, NULL, NULL, 5, 'Trip of a lifetime! Released turtles, surfed, climbed Mt Batur for sunrise, made jewelry, quad biked through waterfalls, white water rafted! Jay, Ruby, and Nyoman were incredible guides. Best experience ever!', 'bali-explorer', 'Bali Explorer', '22 Sep 2025', 1, 0, 5, '2026-04-01 13:05:21.000', '2026-04-01 13:05:21.000');
INSERT IGNORE INTO `reviews` (`id`, `authorName`, `authorAge`, `authorLocation`, `authorPhoto`, `rating`, `reviewText`, `tourSlug`, `tourName`, `reviewDate`, `published`, `featured`, `sortOrder`, `createdAt`, `updatedAt`) VALUES (6, 'Dean Garrity', NULL, NULL, NULL, 5, 'Amazing experience from start to finish. The reps were fantastic and the activities were perfectly balanced. Mt Batur sunrise was breathtaking and the turtle sanctuary was a highlight. Would definitely travel with Ace again!', 'bali-explorer', 'Bali Explorer', '18 Sep 2025', 1, 0, 6, '2026-04-01 13:05:21.000', '2026-04-01 13:05:21.000');
INSERT IGNORE INTO `reviews` (`id`, `authorName`, `authorAge`, `authorLocation`, `authorPhoto`, `rating`, `reviewText`, `tourSlug`, `tourName`, `reviewDate`, `published`, `featured`, `sortOrder`, `createdAt`, `updatedAt`) VALUES (7, 'Evelyn', NULL, NULL, NULL, 5, 'I went on the Bali Island Hopper trip in September 2025 and I can honestly say that it was one of the best trips of my life. Having never flown outside of Europe, it was comforting to know that the reps Ruby and Jay were on hand to help with any questions.', 'bali-island-hopper', 'Bali Island Hopper', '05 Oct 2025', 1, 1, 7, '2026-04-01 13:05:21.000', '2026-04-01 13:05:21.000');
INSERT IGNORE INTO `reviews` (`id`, `authorName`, `authorAge`, `authorLocation`, `authorPhoto`, `rating`, `reviewText`, `tourSlug`, `tourName`, `reviewDate`, `published`, `featured`, `sortOrder`, `createdAt`, `updatedAt`) VALUES (8, 'Carly J', NULL, NULL, NULL, 5, 'I did the Bali Island Hopper in September and absolutely loved the snorkelling, Gili T was amazing! Seeing the manta rays was probably the best experience I\'ve ever had in my life! Jay and Ruby were incredible. Will absolutely be booking another tour with Ace!!', 'bali-island-hopper', 'Bali Island Hopper', '09 Oct 2025', 1, 1, 8, '2026-04-01 13:05:21.000', '2026-04-01 13:05:21.000');
INSERT IGNORE INTO `reviews` (`id`, `authorName`, `authorAge`, `authorLocation`, `authorPhoto`, `rating`, `reviewText`, `tourSlug`, `tourName`, `reviewDate`, `published`, `featured`, `sortOrder`, `createdAt`, `updatedAt`) VALUES (9, 'Jayden', NULL, NULL, NULL, 5, 'Loved every minute of my trip, from the activities, organisation, communication and the friendliness of both Jay and Ruby!', 'bali-island-hopper', 'Bali Island Hopper', '09 Oct 2025', 1, 0, 9, '2026-04-01 13:05:21.000', '2026-04-01 13:05:21.000');
INSERT IGNORE INTO `reviews` (`id`, `authorName`, `authorAge`, `authorLocation`, `authorPhoto`, `rating`, `reviewText`, `tourSlug`, `tourName`, `reviewDate`, `published`, `featured`, `sortOrder`, `createdAt`, `updatedAt`) VALUES (10, 'Liberty Abbott', NULL, NULL, NULL, 5, 'I can\'t thank Ace enough! Firstly, I was added into a group chat with everyone. This made things so much easier as it broke the ice before we met each other. From there everything was effortless as all the activities & accommodation were booked so I didn\'t have to lift a finger!', 'bali-island-hopper', 'Bali Island Hopper', '13 Oct 2025', 1, 0, 10, '2026-04-01 13:05:21.000', '2026-04-01 13:05:21.000');
INSERT IGNORE INTO `reviews` (`id`, `authorName`, `authorAge`, `authorLocation`, `authorPhoto`, `rating`, `reviewText`, `tourSlug`, `tourName`, `reviewDate`, `published`, `featured`, `sortOrder`, `createdAt`, `updatedAt`) VALUES (11, 'Lily-Mae', NULL, NULL, NULL, 5, 'This was my second trip with Ace and once again, it was incredible! It\'s perfect if you want to travel but don\'t feel confident going solo. I met so many lovely people and had the best time. The places we stayed in were super clean and comfy too. Thanks again, Ace!', 'bali-island-hopper', 'Bali Island Hopper', '17 Oct 2025', 1, 0, 11, '2026-04-01 13:05:21.000', '2026-04-01 13:05:21.000');
INSERT IGNORE INTO `reviews` (`id`, `authorName`, `authorAge`, `authorLocation`, `authorPhoto`, `rating`, `reviewText`, `tourSlug`, `tourName`, `reviewDate`, `published`, `featured`, `sortOrder`, `createdAt`, `updatedAt`) VALUES (12, 'Ellie Heinsen', NULL, NULL, NULL, 5, 'Absolutely Perfect! Mixture of culture, exploring, and partying. Ace team was helpful from booking to end. First solo trip and it boosted my confidence to travel more.', 'thailand-intro', 'Thailand Intro', '18 Sep 2025', 1, 0, 12, '2026-04-01 13:05:21.000', '2026-04-01 13:05:21.000');
INSERT IGNORE INTO `reviews` (`id`, `authorName`, `authorAge`, `authorLocation`, `authorPhoto`, `rating`, `reviewText`, `tourSlug`, `tourName`, `reviewDate`, `published`, `featured`, `sortOrder`, `createdAt`, `updatedAt`) VALUES (13, 'Maisie', NULL, NULL, NULL, 5, 'Incredible trip with perfect balance of activities and free time. The group vibe was fantastic and our guides made everything seamless. Elephant sanctuary was the highlight!', 'thailand-intro', 'Thailand Intro', '15 Aug 2025', 1, 0, 13, '2026-04-01 13:05:21.000', '2026-04-01 13:05:21.000');
INSERT IGNORE INTO `reviews` (`id`, `authorName`, `authorAge`, `authorLocation`, `authorPhoto`, `rating`, `reviewText`, `tourSlug`, `tourName`, `reviewDate`, `published`, `featured`, `sortOrder`, `createdAt`, `updatedAt`) VALUES (14, 'Dean Garrity', NULL, NULL, NULL, 5, 'Went solo and made friends for life. The itinerary was perfectly paced with incredible experiences every day. Tipsy tubing in Pai was absolutely wild!', 'thailand-intro', 'Thailand Intro', '03 Jul 2025', 1, 0, 14, '2026-04-01 13:05:21.000', '2026-04-01 13:05:21.000');
