INSERT IGNORE INTO `faqs` (`id`, `question`, `answer`, `category`, `sortOrder`, `published`, `createdAt`, `updatedAt`) VALUES (1, 'How do I book a tour?', 'Booking is simple! Head to our booking page at booking.acetravelexperiences.com, choose your tour and departure date, and secure your place with a £60 deposit. You\'ll receive a confirmation email with all the details and be added to your tour\'s private WhatsApp group.', 'booking', 1, 1, '2026-04-01 13:05:21.000', '2026-04-01 13:05:21.000');
INSERT IGNORE INTO `faqs` (`id`, `question`, `answer`, `category`, `sortOrder`, `published`, `createdAt`, `updatedAt`) VALUES (2, 'How much is the deposit?', 'We require a £60 deposit to secure your place on any tour. The remaining balance is due 30 days before your departure date. We offer flexible payment plans so you can spread the cost — just get in touch if you\'d like to set one up.', 'booking', 2, 1, '2026-04-01 13:05:21.000', '2026-04-01 13:05:21.000');
INSERT IGNORE INTO `faqs` (`id`, `question`, `answer`, `category`, `sortOrder`, `published`, `createdAt`, `updatedAt`) VALUES (3, 'When is the final payment due?', 'Your final balance is due 30 days before your departure date. We\'ll send you a reminder email in advance. If you book within 30 days of departure, the full amount is payable at the time of booking.', 'booking', 3, 1, '2026-04-01 13:05:21.000', '2026-04-01 13:05:21.000');
INSERT IGNORE INTO `faqs` (`id`, `question`, `answer`, `category`, `sortOrder`, `published`, `createdAt`, `updatedAt`) VALUES (4, 'What is your cancellation policy?', 'If you cancel more than 60 days before departure, you\'ll receive a full refund minus the £60 deposit. Cancellations between 30-60 days before departure will receive a 50% refund. Cancellations within 30 days of departure are non-refundable. We strongly recommend taking out comprehensive travel insurance.', 'booking', 4, 1, '2026-04-01 13:05:21.000', '2026-04-01 13:05:21.000');
INSERT IGNORE INTO `faqs` (`id`, `question`, `answer`, `category`, `sortOrder`, `published`, `createdAt`, `updatedAt`) VALUES (5, 'Can I transfer my booking to another date?', 'Yes! You can transfer your booking to another available departure date subject to availability. Please contact us at least 30 days before your original departure date. A £25 admin fee applies for date changes.', 'booking', 5, 1, '2026-04-01 13:05:21.000', '2026-04-01 13:05:21.000');
INSERT IGNORE INTO `faqs` (`id`, `question`, `answer`, `category`, `sortOrder`, `published`, `createdAt`, `updatedAt`) VALUES (6, 'Do I need travel insurance?', 'Yes, travel insurance is mandatory for all ACE Travel tours. You must have a policy that covers medical emergencies, trip cancellation, and repatriation. We recommend getting insured as soon as you book. We can recommend reputable providers if you need help finding cover.', 'travel', 6, 1, '2026-04-01 13:05:21.000', '2026-04-01 13:05:21.000');
INSERT IGNORE INTO `faqs` (`id`, `question`, `answer`, `category`, `sortOrder`, `published`, `createdAt`, `updatedAt`) VALUES (7, 'Do I need a visa?', 'Visa requirements depend on your nationality and destination. For Thailand, UK and EU passport holders currently receive a free 30-day visa on arrival. For Bali (Indonesia), most nationalities receive a free 30-day visa on arrival. We recommend checking the latest requirements with your country\'s foreign office before travelling.', 'travel', 7, 1, '2026-04-01 13:05:21.000', '2026-04-01 13:05:21.000');
INSERT IGNORE INTO `faqs` (`id`, `question`, `answer`, `category`, `sortOrder`, `published`, `createdAt`, `updatedAt`) VALUES (8, 'What vaccinations do I need?', 'We recommend consulting your GP or a travel health clinic at least 6-8 weeks before departure. Common vaccinations for Southeast Asia include Hepatitis A, Typhoid, and Tetanus. Malaria prophylaxis may be recommended for some areas. Your doctor will advise based on your personal health history.', 'travel', 8, 1, '2026-04-01 13:05:21.000', '2026-04-01 13:05:21.000');
INSERT IGNORE INTO `faqs` (`id`, `question`, `answer`, `category`, `sortOrder`, `published`, `createdAt`, `updatedAt`) VALUES (9, 'What should I pack?', 'Light, breathable clothing is key for Southeast Asia\'s tropical climate. Pack comfortable walking shoes, flip flops, a light rain jacket, sun cream, insect repellent, and a small day bag. We\'ll send you a full packing list when you book. Remember to pack modestly for temple visits — shoulders and knees should be covered.', 'travel', 9, 1, '2026-04-01 13:05:22.000', '2026-04-01 13:05:22.000');
INSERT IGNORE INTO `faqs` (`id`, `question`, `answer`, `category`, `sortOrder`, `published`, `createdAt`, `updatedAt`) VALUES (10, 'Can I join a tour on my own?', 'Absolutely! The majority of our travellers join solo. Our tours are specifically designed for solo travellers who want to meet like-minded people and explore the world together. You\'ll be added to a private WhatsApp group before departure to start getting to know your fellow travellers.', 'tours', 10, 1, '2026-04-01 13:05:22.000', '2026-04-01 13:05:22.000');
INSERT IGNORE INTO `faqs` (`id`, `question`, `answer`, `category`, `sortOrder`, `published`, `createdAt`, `updatedAt`) VALUES (11, 'What is the group size?', 'Our tours typically have between 15 and 30 travellers, which we\'ve found is the perfect size. Large enough to always have someone to hang out with, but small enough to feel like a close-knit group rather than a coach tour.', 'tours', 11, 1, '2026-04-01 13:05:22.000', '2026-04-01 13:05:22.000');
INSERT IGNORE INTO `faqs` (`id`, `question`, `answer`, `category`, `sortOrder`, `published`, `createdAt`, `updatedAt`) VALUES (12, 'What age range are the tours for?', 'Our tours are designed for 18-35 year olds. This age range keeps the group energy consistent and ensures everyone is at a similar life stage. If you\'re slightly outside this range and feel the tours would be right for you, please get in touch and we\'ll do our best to accommodate.', 'tours', 12, 1, '2026-04-01 13:05:22.000', '2026-04-01 13:05:22.000');
INSERT IGNORE INTO `faqs` (`id`, `question`, `answer`, `category`, `sortOrder`, `published`, `createdAt`, `updatedAt`) VALUES (13, 'Are the tours suitable for first-time travellers?', 'Yes! Many of our travellers are heading overseas for the first time. Our experienced reps handle all the logistics, accommodation, and activities so you can focus on having the time of your life. We\'ll guide you through everything from airport arrivals to local customs.', 'tours', 13, 1, '2026-04-01 13:05:22.000', '2026-04-01 13:05:22.000');
INSERT IGNORE INTO `faqs` (`id`, `question`, `answer`, `category`, `sortOrder`, `published`, `createdAt`, `updatedAt`) VALUES (14, 'What is included in the tour price?', 'All accommodation, a full activities package, group transport between destinations, and most meals are included. You\'ll also get an experienced ACE rep with you throughout, a local guide, access to our private members group, and flight assistance. Check the individual tour pages for the full inclusions list.', 'tours', 14, 1, '2026-04-01 13:05:22.000', '2026-04-01 13:05:22.000');
INSERT IGNORE INTO `faqs` (`id`, `question`, `answer`, `category`, `sortOrder`, `published`, `createdAt`, `updatedAt`) VALUES (15, 'Do you offer scuba diving on the tours?', 'Yes! We offer scuba diving as an optional add-on on our Thailand Island Hopper and Bali Island Hopper tours. We partner with certified local dive schools at each destination. You can choose from a Basic Diver course (£100) or a full Open Water certification (£350). No experience is necessary for either course.', 'addons', 15, 1, '2026-04-01 13:05:22.000', '2026-04-01 13:05:22.000');
INSERT IGNORE INTO `faqs` (`id`, `question`, `answer`, `category`, `sortOrder`, `published`, `createdAt`, `updatedAt`) VALUES (16, 'Do I need any experience to try scuba diving?', 'No experience is needed at all! Our Basic Diver course is perfect for complete beginners and takes place in shallow, calm waters with a fully qualified instructor. For the Open Water certification, you\'ll complete theory, pool sessions, and open water dives over 3-4 days. Our partner dive schools are fully certified and have excellent safety records.', 'addons', 16, 1, '2026-04-01 13:05:22.000', '2026-04-01 13:05:22.000');
